import{_ as e,o as a,c as n,aj as d}from"./framework.js";const p=JSON.parse('{"title":"Add Content | Documentation","description":"Create a content model and content items so pages can retrieve managed data from Admin.","frontmatter":{"title":"Add Content | Documentation","description":"Create a content model and content items so pages can retrieve managed data from Admin.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/quick-start/add-content.html"}]]},"headers":[],"relativePath":"quick-start/add-content.md","filePath":"en/quick-start/add-content.md","lastUpdated":1786616613000}'),o={name:"quick-start/add-content.md"};function r(i,t,s,c,l,h){return a(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="add-content" tabindex="-1">Add Content <a class="header-anchor" href="#add-content" aria-label="Permalink to &quot;Add Content&quot;">​</a></h1><blockquote><p>Create a content model and content items so pages can retrieve managed data from Admin.</p></blockquote><h2 id="create-a-content-type-first" tabindex="-1">Create a Content Type First <a class="header-anchor" href="#create-a-content-type-first" aria-label="Permalink to &quot;Create a Content Type First&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Menu path</td><td>Site Admin -&gt; Content -&gt; Content Types</td></tr><tr><td>Deep link</td><td><code>/_Admin/contents/types?SiteId={site-guid}</code></td></tr><tr><td>Detailed documentation</td><td><a href="/kb-docs/cms/content/content-types.html">CMS: Content Types</a></td></tr></tbody></table><p>A content type defines the fields available to content. For your first model, start with a simple structure:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Suggested fields</th></tr></thead><tbody><tr><td>News</td><td>Title, summary, cover image, body, and publication date</td></tr><tr><td>Product showcase</td><td>Name, image, description, price, and order</td></tr><tr><td>FAQ</td><td>Question, answer, category, and pinned status</td></tr></tbody></table><h2 id="create-a-content-folder" tabindex="-1">Create a Content Folder <a class="header-anchor" href="#create-a-content-folder" aria-label="Permalink to &quot;Create a Content Folder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Menu path</td><td>Site Admin -&gt; Content -&gt; Contents</td></tr><tr><td>Deep link</td><td><code>/_Admin/contents?SiteId={site-guid}</code></td></tr><tr><td>Detailed documentation</td><td><a href="/kb-docs/cms/content/contents-folders-list.html">CMS: Content List</a></td></tr></tbody></table><p>A content folder turns a content type into a maintainable data collection. After creating it, open the folder and add several content items as test data for the page.</p><h2 id="use-content-on-a-page" tabindex="-1">Use Content on a Page <a class="header-anchor" href="#use-content-on-a-page" aria-label="Permalink to &quot;Use Content on a Page&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Recommended use</th><th>Documentation</th></tr></thead><tbody><tr><td>Template binding</td><td>Render lists, details, and fields directly on a page</td><td><a href="/kb-docs/templateEngine/binding/">Template Binding Syntax</a></td></tr><tr><td><code>k-data</code></td><td>Declare queries, mappings, and exports in a template</td><td><a href="/kb-docs/templateEngine/k-data/">k-data</a></td></tr><tr><td>KScript API</td><td>Let the frontend retrieve content through a JSON endpoint</td><td><a href="/kb-docs/api/content/">k.content</a></td></tr></tbody></table><p>If you are not ready to write scripts, begin with template binding or <code>k-data</code>. Create an API when you need filtering, pagination, permissions, or data shared across clients.</p><h2 id="common-checks" tabindex="-1">Common Checks <a class="header-anchor" href="#common-checks" aria-label="Permalink to &quot;Common Checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to check</th></tr></thead><tbody><tr><td>The page has no data</td><td>Confirm that the content folder contains items and the field names match the template</td></tr><tr><td>Fields render incorrectly</td><td>Check content-type field types, required settings, and default values</td></tr><tr><td>The list order is incorrect</td><td>Check content item order, publication time, or query conditions</td></tr><tr><td>Multilingual content is missing</td><td>Check the content language and site language settings</td></tr></tbody></table><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Continue to <a href="./publish-domain.html">Publish and Domains</a>, or go directly to <a href="./add-script-api.html">Write Your First KScript API</a>.</p>',16)])])}const u=e(o,[["render",r]]);export{p as __pageData,u as default};
